	public static readonly IReadOnlySet<AnalysisServicesErrorCode> KnownASUserErrorCodes = new HashSet<AnalysisServicesErrorCode> { AnalysisServicesErrorCode.PFE_EFFECTIVE_USER_NAME_USED_BY_NON_WORKSPACE_ADMIN_NOT_ALLOWED };

	public static int ToInt(this AnalysisServicesErrorCode errorCode)
	{
		return (int)errorCode;
	}

	public static string ToErrorString(this AnalysisServicesErrorCode errorCode)
	{
		if (Enum.IsDefined(typeof(AnalysisServicesErrorCode), errorCode))
		{
			return errorCode.ToString();
		}
		return string.Format(CultureInfo.InvariantCulture, "UNKNOWN_ERROR: 0x{0:X8}", (uint)errorCode);
	}

	public static AnalysisServicesErrorCode ToErrorCodeEnum(this int errorCode)
	{
		return (AnalysisServicesErrorCode)errorCode;
	}
}
